const HEAD=`<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
<meta name="design_doc_mode" content="canvas">
<link rel="stylesheet" href="${DS}styles.css">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="crossorigin">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Barlow+Condensed:wght@500;600;700&display=swap">
<script src="${DS}_ds_bundle.js"></script>
<style>
  body { margin: 0; background: var(--color-neutral-200); }
  a { color: var(--color-accent-2-700); }
  a:hover { color: var(--color-accent-2-800); }
</style>
</helmet>
`;
const out=[];
for(const G of GROUPS){let h=HEAD+`<div style="padding:56px;display:flex;flex-direction:column;gap:72px;font-family:var(--font-body);width:max-content">
<div style="max-width:900px"><div class="kt-label" style="margin-bottom:8px">BDS-CHG-001 v0.8 (revision 938ccb01) · §10 · KenTender Industry design system</div><h1 style="margin:0 0 10px;font-family:var(--font-heading)">${G.title}</h1><p style="font-size:15px;line-height:1.6;margin:0 0 20px;color:var(--color-neutral-800)">Every base artboard and named variant is drawn in full at 1440 × 1024 and 390 × 844, side by side. Each page is one .kt-page sheet on the §10.1 shell; journey tracker and next-step block use .kt-guidance per §10.19. Fixture context sits in the caption, outside the artboard.</p>
<div style="display:flex;flex-wrap:wrap;gap:8px 24px;font-size:14px">${GROUPS.map(g=>`<a href="${encodeURI(g.file)}.dc.html"${g===G?' style="font-weight:700"':''}>${g.title}</a>`).join('')}</div>
<div style="display:flex;flex-wrap:wrap;gap:6px 18px;font-size:13px;margin-top:12px">${G.arts.map(([n,t])=>`<a href="#des${n}">DES-${n} ${t}</a>`).join('')}</div></div>
`;
 for(const [n,t,fn,vars] of G.arts){h+=`<section id="des${n}" style="display:flex;flex-direction:column;gap:40px">\n<h2 style="margin:0;font-family:var(--font-heading);font-size:30px;border-bottom:2px solid var(--color-neutral-400);padding-bottom:8px">BDS-DES-${n} · ${t}</h2>\n`;
  for(const [v,cap,lab] of vars){const id=lab||(v?`BDS-DES-${n}-${v}`:`BDS-DES-${n}`);h+=`<div data-screen-label="${id}" style="display:flex;flex-direction:column;gap:12px"><div style="font-size:14px"><strong>${id}</strong> <span style="color:var(--color-neutral-700)">— ${cap}</span></div><div style="display:flex;gap:40px;align-items:flex-start">${fn('d',v)}${fn('n',v)}</div></div>\n`}
  h+='</section>\n'}
 h+='</div>\n</x-dc>\n</body>\n</html>\n';out.push([G.file+'.dc.html',h])}
for(const [f,h] of out){await saveFile(f,h);log(f,h.length)}
